export const ATS_DATE_RE = /^(present|current|now|ongoing|\d{1,2}\/\d{2}(\d{2})?|(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\s?\d{4})$/i;
export const MEASURABLE_RESULT_RE = /(?:\d+(?:\.\d+)?%|\d+(?:\.\d+)?x|\$\s?\d+(?:,\d{3})*(?:\.\d+)?[KMB]?|\d+(?:,\d{3})*(?:\.\d+)?[KMB]?\+?|\d+\s*(?:hours?|hrs?|days?|weeks?|months?|years?)|(?:team of|managed|led|supervised)\s+\d+|\d+\s*(?:members?|people|employees?|clients?|users?|customers?)|\d+(?:\.\d+)?\/\d+)/i;
